import jwt from "jsonwebtoken";
import config from "../config/envConfig.js";
import { fail } from "../util/response.js";

export function authenticateToken(req, res, next) {
  try {
    //const authHeader = req.headers["Authorization"];
    const { ACCESS_TOKEN_SECRET } = config;
    const authHeader = req.headers.authorization || req.headers.Authorization;

    //console.log("Received Authorization header:", authHeader); // Debug

    if (!authHeader) {
      console.log("from authenticateTocken: No auth header present");
      return fail(res, "Unauthorized", 401);
    }
    const token = authHeader && authHeader.split(" ")[1];

    if (!token) return fail(res, "Unauthorized - Missing token", 401);

    jwt.verify(token, ACCESS_TOKEN_SECRET, (err, user) => {
      if (err) {
        // Differentiate between expired and invalid tokens
        if (err.name === "TokenExpiredError") {
          console.log("error" + err.name);
          return fail(res, "Token expired", 401);
        }
        return fail(res, "Forbidden - Invalid token", 403);
      }
      req.user = user;
      next();
    });
  } catch (error) {
    console.log({ error });
    return fail(res, "Unprocessable Error", 422, { details: error.message });
  }
}

// Express middleware
export const apiClientValidator = (req, res, next) => {
  // Check for a custom header only your API instance sends
  if (!req.headers["x-api-client"] || req.headers["x-api-client"] !== "rcm-app-v1") {
    // console.log("error blocked by apiClientValidator");
    return fail(res, "Sorry, You are unathenticate to access this endpoint", 403);
  } else {
    //  console.log("not blocked by APIClientValidator");
    next();
  }
};
